14	/* ── the two loading screens ─────────────────────────────────────────── */
15	
16	export function Building({
17	  variant,
18	  onDone,
19	}: {
20	  variant: 'recs' | 'schedule';
21	  onDone: () => void;
22	}) {
23	  const copy =
24	    variant === 'recs'
25	      ? {
26	          title: 'Going through the research for your goals.',
27	          lines: ['Reading the entries', 'Matching them to your goals', 'Checking for overlaps'],
28	          min: 2200,
29	        }
30	      : {
31	          title: 'Fitting these around your meals and sleep.',
32	          lines: ['Placing the morning block', 'Anchoring what needs food', 'Filling the wind-down'],
33	          min: 1800,
34	        };
35	
36	  const [line, setLine] = useState(0);
37	
38	  useEffect(() => {
39	    const cycle = setInterval(() => setLine((n) => (n + 1) % copy.lines.length), 700);
40	    // held for the minimum even when the real work finishes first, so it reads
41	    // as thought rather than a flash
42	    const done = setTimeout(onDone, copy.min);
43	    return () => {
44	      clearInterval(cycle);
45	      clearTimeout(done);
46	    };
47	    // eslint-disable-next-line react-hooks/exhaustive-deps
48	  }, [variant]);
49	
50	  return (
51	    <Screen center>
52	      <DrawingArc />
53	      <p className="ob-sub" style={{ maxWidth: 280, marginTop: 30 }}>
54	        {copy.title}
55	      </p>
56	      <p className="ob-loading-status" aria-live="polite">
57	        {copy.lines[line]}
58	      </p>
59	    </Screen>
60	  );
61	}
