63	/** The Today arc, drawing itself. */
64	function DrawingArc() {
65	  const R = 150;
66	  const SWEEP = 88;
67	  const HALF = SWEEP / 2;
68	  const W = 220;
69	  const CX = W / 2;
70	  const CY = R + 7;
71	  const H = Math.ceil(R * (1 - Math.cos((HALF * Math.PI) / 180)) + 14);
72	  const pt = (deg: number) => {
73	    const r = (deg * Math.PI) / 180;
74	    return [CX + R * Math.sin(r), CY - R * Math.cos(r)];
75	  };
76	  const [a1, b1] = pt(-HALF);
77	  const [a2, b2] = pt(HALF);
78	  const d = `M${a1.toFixed(1)} ${b1.toFixed(1)} A${R} ${R} 0 0 1 ${a2.toFixed(1)} ${b2.toFixed(1)}`;
79	  return (
80	    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} fill="none" aria-hidden>
81	      <path d={d} stroke="var(--card)" strokeWidth="9" strokeLinecap="round" />
82	      <path className="ob-arc-draw" d={d} stroke="var(--accent)" strokeWidth="9" strokeLinecap="round" pathLength={1} />
83	    </svg>
84	  );
