99	export function useRecommendations(
100	  goalIds: string[],
101	  currentStack: string[],
102	  age?: number | null,
103	  sex?: 'm' | 'f' | 'na' | null,
104	) {
105	  const [entries, setEntries] = useState<GlossaryEntry[] | null>(null);
106	  const [refs, setRefs] = useState<Record<string, NutrientReference[]>>({});
107	  useEffect(() => {
108	    listGlossary(200)
109	      .then((rows) => {
110	        setEntries(rows);
111	        return getNutrientReference(rows.map((r) => r.id));
112	      })
113	      .then((m) => m && setRefs(m))
114	      .catch(() => setEntries([]));
115	  }, []);
116	
117	  return useMemo(() => {
118	    if (!entries) return null;
119	    const ids = goalIds.length ? goalIds : DEFAULT_GOAL_IDS;
120	    const wanted = new Set(ids.flatMap((g) => GOAL_BY_ID[g]?.tags ?? []));
121	    const already = new Set(currentStack.map((s) => s.toLowerCase()));
122	
123	    /* Supplements only. Ranking peptides for a specific person is a
124	       recommendation whether or not an amount is attached, and it is the same
125	       rule the assistant is held to — enforced here in code rather than left
126	       to whatever the tag overlap happens to return. Every goal was returning
127	       two to four peptides in its top six before this. */
128	    const EVIDENCE_RANK = { strong: 0, mixed: 1, thin: 2 } as const;
129	    const rank = (e: GlossaryEntry) => EVIDENCE_RANK[e.evidence ?? 'thin'] ?? 2;
130	
131	    const scored = entries
132	      .filter((e) => (e.kind ?? 'peptide') === 'supplement')
133	      // no point suggesting what they told us they already take
134	      .filter((e) => !already.has(e.name.toLowerCase()))
135	      .map((e) => {
136	        const hits = (e.goal_tags ?? []).filter((t) => wanted.has(t));
137	        return { e, hits };
138	      })
139	      .filter((x) => x.hits.length > 0)
140	      /* Goal overlap first, then how good the evidence is. The tie-break used
141	         to be the product name, which sorted alphabetically and quietly put
142	         every brand beginning with A at the top of a list that looks like a
143	         ranking. */
144	      .sort(
145	        (a, b) =>
146	          b.hits.length - a.hits.length ||
147	          rank(a.e) - rank(b.e) ||
148	          a.e.name.localeCompare(b.e.name),
149	      );
150	
151	    const goalNames = ids.map((g) => GOAL_BY_ID[g]?.name ?? g);
152	
153	    return {
154	      picks: scored.slice(0, 6).map(({ e, hits }, i) => {
155	        const r = pickReference(refs[e.id], age, sex);
156	        return {
157	          id: e.id,
158	          name: e.name,
159	          route: e.route,
160	          amount: r?.rda != null ? `${r.rda} ${r.unit}` : '',
161	          why: `Tagged ${hits.join(' and ')} — matches ${goalNames.length > 1 ? 'your goals' : goalNames[0]?.toLowerCase()}.`,
162	          selected: i < 3,
163	        };
164	      }),
165	      leftOut: {
166	        alreadyTaking: entries
167	          .filter((e) => already.has(e.name.toLowerCase()))
168	          .map((e) => e.name),
169	        noMatch: scored.length > 6 ? scored.slice(6).map((x) => x.e.name) : [],
170	        goalNames,
171	      },
172	    };
173	  }, [entries, refs, goalIds, currentStack, age, sex]);
174	}
