176	export function Recommendations({
177	  goalIds,
178	  currentStack,
179	  age,
180	  sex,
181	  onDone,
182	}: {
183	  goalIds: string[];
184	  currentStack: string[];
185	  age?: number | null;
186	  sex?: 'm' | 'f' | 'na' | null;
187	  onDone: (picks: Recommendation[]) => void;
188	}) {
189	  const data = useRecommendations(goalIds, currentStack, age, sex);
190	  const [picks, setPicks] = useState<Recommendation[] | null>(null);
191	
192	  useEffect(() => {
193	    if (data && !picks) setPicks(data.picks);
194	  }, [data, picks]);
195	
196	  if (!data || !picks) {
197	    return (
198	      <Screen center>
199	        <p className="ob-sub">Loading…</p>
200	      </Screen>
201	    );
202	  }
203	
204	  const chosen = picks.filter((p) => p.selected);
205	
206	  return (
207	    <Screen
208	      scroll
209	      footer={
210	        <Cta onClick={() => onDone(chosen)} disabled={chosen.length === 0}>
211	          Create schedule
212	        </Cta>
213	      }
214	    >
215	      <Title>What we found</Title>
216	      <Sub>
217	        Matched to {data.leftOut.goalNames.join(' and ').toLowerCase()}, ranked by how many of your
218	        goals each one covers and then by the strength of the evidence. Untick anything you
219	        don’t want.
220	      </Sub>
221	
222	      <div className="ob-recs">
223	        {picks.map((r) => (
224	          <button
225	            key={r.id}
226	            className={`ob-rec${r.selected ? ' on' : ''}`}
227	            aria-pressed={r.selected}
228	            onClick={() =>
229	              setPicks((ps) => ps!.map((p) => (p.id === r.id ? { ...p, selected: !p.selected } : p)))
230	            }
231	          >
232	            <span className="ob-rec-main">
233	              <span className="ob-card-title">{r.name}</span>
234	              {/* The app holds no dose for anything and will not invent one --
235	                  the glossary carries category, mechanism, storage and route,
236	                  never an amount. See legal.md. The slot stays, labelled. */}
237	              <span className="ob-rec-dose">
238	                {r.amount ? `${r.amount} a day · ${r.route}` : `${r.route} · you set the amount`}
239	              </span>
240	              <span className="ob-rec-why">{r.why}</span>
241	              <span className="ob-rec-link">Read the research →</span>
242	            </span>
243	            <span className={`ob-tick${r.selected ? ' on' : ''}`}>
244	              {r.selected && (
245	                <svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="var(--bg)" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
246	                  <path d="M2.5 6.2 4.8 8.5 9.5 3.5" />
247	                </svg>
248	              )}
249	            </span>
250	          </button>
251	        ))}
252	      </div>
253	
254	      {/* The part people screenshot. Do not cut it. */}
255	      <div className="ob-left-out">
256	        <h2>What was left out</h2>
257	        {data.leftOut.alreadyTaking.length > 0 && (
258	          <p>
259	            <b>Already in your stack:</b> {data.leftOut.alreadyTaking.join(', ')}. No point suggesting
260	            what you are taking.
261	          </p>
262	        )}
263	        {data.leftOut.noMatch.length > 0 && (
264	          <p>
265	            <b>Matched but ranked lower:</b> {data.leftOut.noMatch.slice(0, 6).join(', ')}. Fewer of
266	            your goals matched their tags.
267	          </p>
268	        )}
269	        <p>
270	          Everything else in the library is tagged for goals you did not pick. Nothing was excluded
271	          for being unpopular or unprofitable — the ranking is goal-tag overlap and nothing else.
272	        </p>
273	      </div>
274	    </Screen>
275	  );
276	}
