278	/* ── the draggable schedule ──────────────────────────────────────────── */
279	
280	interface Slot {
281	  id: string;
282	  name: string;
283	  time: string;
284	}
285	
286	const buildSlots = (meals: Meal[], wake: string, sleep: string): Slot[] => {
287	  const s: Slot[] = [{ id: 'morning', name: 'Morning', time: wake }];
288	  for (const m of [...meals].sort((a, b) => toMinutes(a.time) - toMinutes(b.time))) {
289	    s.push({ id: m.id, name: m.name, time: m.time });
290	  }
291	  s.push({ id: 'winddown', name: 'Wind-down', time: fromMinutes(toMinutes(sleep) - 60) });
292	  const seen = new Set<string>();
293	  return s.filter((x) => (seen.has(x.time) ? false : (seen.add(x.time), true)));
294	};
295	
296	export function ScheduleBuilder({
297	  picks,
298	  meals,
299	  wake,
300	  sleep,
301	  onDone,
302	}: {
303	  picks: Recommendation[];
304	  meals: Meal[];
305	  wake: string;
306	  sleep: string;
307	  onDone: (schedule: { id: string; time: string }[]) => void;
308	}) {
309	  const slots = useMemo(() => buildSlots(meals, wake, sleep), [meals, wake, sleep]);
310	  const [placed, setPlaced] = useState<Record<string, string>>(() =>
311	    Object.fromEntries(picks.map((p, i) => [p.id, slots[i % slots.length].id])),
312	  );
313	  const [dragging, setDragging] = useState<string | null>(null);
314	  const [over, setOver] = useState<{ slot: string; bad: boolean } | null>(null);
315	  const [shake, setShake] = useState<string | null>(null);
316	  const [message, setMessage] = useState<string | null>(null);
317	  const hold = useRef<number | null>(null);
318	
319	  const ctx = { mealTimes: meals.map((m) => m.time), sleepTime: sleep };
320	  const slotById = Object.fromEntries(slots.map((s) => [s.id, s]));
321	
322	  const itemsIn = (slotId: string) => picks.filter((p) => placed[p.id] === slotId);
323	
324	  const others = (movingId: string): ScheduledItem[] =>
325	    picks
326	      .filter((p) => p.id !== movingId)
327	      .map((p) => ({ id: p.id, name: p.name, time: slotById[placed[p.id]]?.time ?? wake }));
328	
329	  const tryDrop = (id: string, slotId: string) => {
330	    const p = picks.find((x) => x.id === id)!;
331	    const target = slotById[slotId];
332	    const violations = checkPlacement({ id, name: p.name, time: target.time }, target.time, others(id), ctx);
333	    const blocking = violations.find((v) => v.severity === 'block');
334	    if (blocking) {
335	      // springs back, shakes, and says which rule -- the shake on its own
336	      // communicates nothing and fails accessibility
337	      setShake(id);
338	      setMessage(blocking.message);
339	      setTimeout(() => setShake(null), 420);
340	      return;
341	    }
342	    setPlaced((m) => ({ ...m, [id]: slotId }));
343	    setMessage(violations[0]?.message ?? null);
344	  };
345	
346	  const startHold = (id: string) => {
347	    hold.current = window.setTimeout(() => setDragging(id), 200);
348	  };
349	  const cancelHold = () => {
350	    if (hold.current) clearTimeout(hold.current);
351	    hold.current = null;
352	  };
353	
354	  const onMove = (e: React.PointerEvent) => {
355	    if (!dragging) return;
356	    const el = document.elementFromPoint(e.clientX, e.clientY)?.closest('[data-slot]') as HTMLElement | null;
357	    if (!el) return setOver(null);
358	    const slotId = el.dataset.slot!;
359	    const p = picks.find((x) => x.id === dragging)!;
360	    const t = slotById[slotId];
361	    const bad = checkPlacement({ id: dragging, name: p.name, time: t.time }, t.time, others(dragging), ctx).some(
362	      (v) => v.severity === 'block',
363	    );
364	    setOver({ slot: slotId, bad });
365	  };
366	
367	  const onUp = () => {
368	    cancelHold();
369	    if (dragging && over) tryDrop(dragging, over.slot);
370	    setDragging(null);
371	    setOver(null);
372	  };
373	
374	  return (
375	    <Screen
376	      scroll
377	      footer={<Cta onClick={() => onDone(picks.map((p) => ({ id: p.id, time: slotById[placed[p.id]].time })))}>Start</Cta>}
378	    >
379	      <Title>Your schedule</Title>
380	      <Sub>Press and hold a card to move it. We’ll say if something can’t go there.</Sub>
381	
382	      <div className="ob-slots" onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}>
383	        {slots.map((s) => (
384	          <div key={s.id}>
385	            <div className="ob-slot-head">
386	              <span className="ob-slot-name">{s.name}</span>
387	              <span className="ob-slot-time">{s.time}</span>
388	            </div>
389	            <div
390	              data-slot={s.id}
391	              className={`ob-slot${over?.slot === s.id ? (over.bad ? ' over-bad' : ' over') : ''}`}
392	            >
393	              {itemsIn(s.id).length === 0 && <div className="ob-slot-empty">Nothing here</div>}
394	              {itemsIn(s.id).map((p) => (
395	                <div
396	                  key={p.id}
397	                  className={`ob-dose-card${dragging === p.id ? ' lifted' : ''}${shake === p.id ? ' shake' : ''}`}
398	                  onPointerDown={() => startHold(p.id)}
399	                  onPointerUp={cancelHold}
400	                  onContextMenu={(e) => e.preventDefault()}
401	                >
402	                  <span className="ob-dose-time">{s.time}</span>
403	                  <span style={{ flex: 1, minWidth: 0 }}>
404	                    <span className="ob-card-title" style={{ display: 'block' }}>
405	                      {p.name}
406	                    </span>
407	                    <span className="ob-caption">{p.route} · you set the amount</span>
408	                  </span>
409	                  <svg className="ob-dose-grip" width="16" height="16" viewBox="0 0 16 16" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden>
410	                    <path d="M3 5.5h10M3 10.5h10" />
411	                  </svg>
412	                </div>
413	              ))}
414	            </div>
415	          </div>
416	        ))}
417	      </div>
418	
419	      {message && (
420	        <div className="ob-conflict" role="alert" aria-live="assertive">
421	          {message}
422	        </div>
423	      )}
424	    </Screen>
425	  );
426	}
427	
428	/* ── done ────────────────────────────────────────────────────────────── */
429	
430	export function Done({ onFinish }: { onFinish: () => void }) {
431	  useEffect(() => {
432	    const t = setTimeout(onFinish, 1400);
433	    return () => clearTimeout(t);
434	  }, [onFinish]);
435	
436	  return (
437	    <Screen center>
438	      <OnboardIllustration name="done" size={110} />
439	      <div style={{ marginTop: 26 }}>
440	        <Title>You’re set</Title>
441	        <Sub>Your first day is on the Today screen.</Sub>
442	      </div>
443	    </Screen>
444	  );
445	}
