1	import { useCallback, useEffect, useMemo, useState } from 'react';
2	import { FLOW, isSkipped, type Step } from './flow';
3	
4	export interface Meal {
5	  id: string;
6	  name: string;
7	  time: string;
8	}
9	
10	export interface OnboardingState {
11	  step: number;
12	  auth: { userId: string | null; email: string | null };
13	  profile: { age: number | null; gender: 'm' | 'f' | 'na' | null };
14	  survey: { q1: string | null; q2: string | null; q3: string | null };
15	  /** what they don't eat — the one answer that moves the most products */
16	  diet: string[];
17	  /** what has not agreed with them before; picks the form, never drops the nutrient */
18	  reactions: string[];
19	  /** free text from "something else". Context for the assistant; never parsed by a rule. */
20	  reactionsNote: string;
21	  /** preferred product forms. A soft re-rank, so an empty list is a valid answer. */
22	  forms: string[];
23	  wake: string;
24	  sleep: string;
25	  meals: Meal[];
26	  currentStack: string[];
27	  goals: string[];
28	  notificationsGranted: boolean;
29	  subscribed: boolean;
30	  recommendations: { id: string; selected: boolean }[];
31	  schedule: { id: string; time: string }[];
32	}
33	
34	export const DEFAULT_MEALS: Meal[] = [
35	  { id: 'breakfast', name: 'Breakfast', time: '08:00' },
36	  { id: 'lunch', name: 'Lunch', time: '13:00' },
37	  { id: 'dinner', name: 'Dinner', time: '19:00' },
38	];
39	
40	export const initialState = (): OnboardingState => ({
41	  step: 0,
42	  auth: { userId: null, email: null },
43	  profile: { age: 25, gender: null },
44	  survey: { q1: null, q2: null, q3: null },
45	  diet: [],
46	  reactions: [],
47	  reactionsNote: '',
48	  forms: [],
49	  wake: '07:00',
50	  sleep: '23:00',
51	  meals: DEFAULT_MEALS.map((m) => ({ ...m })),
52	  currentStack: [],
53	  goals: [],
54	  notificationsGranted: false,
55	  subscribed: false,
56	  recommendations: [],
57	  schedule: [],
58	});
59	
60	/** The answers that also live on `profiles`, in this file's shape. */
61	export interface PersistedAnswers {
62	  diet?: string[] | null;
63	  reactions?: string[] | null;
64	  reactionsNote?: string | null;
65	  forms?: string[] | null;
66	}
67	
68	const KEY = 'pepstack.onboarding.v1';
69	
70	/**
71	 * Persisted on every change rather than at the end. A backgrounded tab on iOS
72	 * can be discarded without warning, and losing eleven screens of answers is the
73	 * kind of thing people do not come back from.
74	 */
75	function load(): OnboardingState {
76	  try {
77	    const raw = localStorage.getItem(KEY);
78	    if (!raw) return initialState();
79	    const parsed = JSON.parse(raw) as Partial<OnboardingState>;
80	    // merge over defaults so a store written by an older build still opens
81	    const base = initialState();
82	    const merged: OnboardingState = {
83	      ...base,
84	      ...parsed,
85	      auth: { ...base.auth, ...parsed.auth },
86	      profile: { ...base.profile, ...parsed.profile },
87	      survey: { ...base.survey, ...parsed.survey },
88	      diet: Array.isArray(parsed.diet) ? parsed.diet : [],
89	      reactions: Array.isArray(parsed.reactions) ? parsed.reactions : [],
90	      reactionsNote: typeof parsed.reactionsNote === 'string' ? parsed.reactionsNote : '',
91	      forms: Array.isArray(parsed.forms) ? parsed.forms : [],
92	      meals: Array.isArray(parsed.meals) ? parsed.meals : base.meals,
93	      currentStack: Array.isArray(parsed.currentStack) ? parsed.currentStack : [],
94	      goals: Array.isArray(parsed.goals) ? parsed.goals : [],
95	      recommendations: Array.isArray(parsed.recommendations) ? parsed.recommendations : [],
96	      schedule: Array.isArray(parsed.schedule) ? parsed.schedule : [],
97	    };
98	    // a step index from a longer or reordered FLOW must not land out of bounds
99	    merged.step = Math.max(0, Math.min(FLOW.length - 1, Number(merged.step) || 0));
100	    return merged;
101	  } catch {
102	    return initialState();
103	  }
104	}
105	
106	export function useOnboardingStore() {
107	  const [state, setState] = useState<OnboardingState>(load);
108	
109	  useEffect(() => {
110	    try {
111	      localStorage.setItem(KEY, JSON.stringify(state));
112	    } catch {
113	      /* private mode, quota — losing persistence is survivable, crashing is not */
114	    }
115	  }, [state]);
116	
117	  const patch = useCallback((p: Partial<OnboardingState>) => {
118	    setState((s) => ({ ...s, ...p }));
119	  }, []);
120	
121	  /**
122	   * Fill in answers already on the profile row — a returning user on a new
123	   * device has nothing in localStorage and should not be asked twice. Only
124	   * fields still empty here are touched, so an answer given on this device
125	   * always wins over an older one coming back from the server.
126	   */
127	  const hydrate = useCallback((p: PersistedAnswers) => {
128	    setState((s) => ({
129	      ...s,
130	      diet: s.diet.length ? s.diet : p.diet ?? [],
131	      reactions: s.reactions.length ? s.reactions : p.reactions ?? [],
132	      reactionsNote: s.reactionsNote || p.reactionsNote || '',
133	      forms: s.forms.length ? s.forms : p.forms ?? [],
134	    }));
135	  }, []);
136	
137	  const goTo = useCallback((step: number) => {
138	    setState((s) => ({ ...s, step: Math.max(0, Math.min(FLOW.length - 1, step)) }));
139	  }, []);
140	
141	  /** Walk over anything the answers so far have made irrelevant. */
142	  const step_ = useCallback((s: OnboardingState, dir: 1 | -1) => {
143	    let i = s.step + dir;
144	    while (i > 0 && i < FLOW.length - 1 && isSkipped(FLOW[i], s.survey)) i += dir;
145	    return Math.max(0, Math.min(FLOW.length - 1, i));
146	  }, []);
147	
148	  const next = useCallback(
149	    () => setState((s) => ({ ...s, step: step_(s, 1) })),
150	    [step_],
151	  );
152	  const back = useCallback(
153	    () => setState((s) => ({ ...s, step: step_(s, -1) })),
154	    [step_],
155	  );
156	
157	  const reset = useCallback(() => {
158	    try {
159	      localStorage.removeItem(KEY);
160	    } catch {
161	      /* ignore */
162	    }
163	    setState(initialState());
164	  }, []);
165	
166	  const step: Step = FLOW[state.step];
167	
168	  return useMemo(
169	    () => ({ state, step, patch, hydrate, goTo, next, back, reset }),
170	    [state, step, patch, hydrate, goTo, next, back, reset],
171	  );
172	}
173	
174	export type OnboardingApi = ReturnType<typeof useOnboardingStore>;
175	
176	/** Has the user finished onboarding at least once on this device? */
177	export const DONE_KEY = 'pepstack.onboarded.v1';
178	export const markOnboarded = () => {
179	  try {
180	    localStorage.setItem(DONE_KEY, '1');
181	  } catch {
182	    /* ignore */
183	  }
184	};
185	export const hasOnboarded = () => {
186	  try {
187	    return localStorage.getItem(DONE_KEY) === '1';
188	  } catch {
189	    return false;
190	  }
191	};
