import { defineConfig, devices } from '@playwright/test';
import { BASE_URL, PORT, SUPABASE_ANON_KEY, SUPABASE_URL } from './tests/e2e/support/env';

/**
 * Four smoke tests against the dev server, with Supabase stubbed inside the
 * page. `npm run build` already proves the bundle compiles; these prove it
 * runs.
 *
 * The dev server is started fresh rather than reused, because the whole run
 * depends on it having been given the env vars below — silently attaching to
 * a server started some other way would test the wrong thing.
 */
export default defineConfig({
  testDir: './tests/e2e',
  fullyParallel: true,
  workers: 2,
  // One retry, because this runs unattended overnight and a machine stall
  // should not be indistinguishable from a broken screen. A real break fails
  // both attempts; a retried pass is still reported as flaky.
  retries: 1,
  timeout: 60_000,
  expect: { timeout: 10_000 },
  reporter: [['list']],
  use: {
    baseURL: BASE_URL,
    trace: 'retain-on-failure',
  },
  projects: [
    {
      name: 'iphone-width',
      // The phone layout, which is the only one shipped. Below 640 the app
      // drops the desktop frame and draws as it does on a device.
      use: { ...devices['Desktop Chrome'], viewport: { width: 393, height: 852 } },
    },
  ],
  webServer: {
    // --host is not optional: Vite otherwise binds localhost, which resolves
    // to ::1 first here, and nothing answers on 127.0.0.1.
    command: `npm run dev -- --port ${PORT} --strictPort --host 127.0.0.1`,
    url: BASE_URL,
    reuseExistingServer: false,
    timeout: 120_000,
    env: {
      VITE_SUPABASE_URL: SUPABASE_URL,
      VITE_SUPABASE_ANON_KEY: SUPABASE_ANON_KEY,
      // Dev skips the paywall by default. The tests walk the flow the way it
      // ships, so item 0.10 — moving the paywall — is covered rather than
      // stepped over.
      VITE_SKIP_PAYWALL: 'false',
    },
  },
});

export interface Goal {
  id: string;
  name: string;
  /** two lines, what the app will actually do — not what the supplement does */
  copy: string;
  /** tags present in the glossary; see the distinct set in migration 0003 */
  tags: string[];
  /** supplied artwork in public/goals; matched to the goal by its glyph */
  img: string;
}

export const GOALS: Goal[] = [
  {
    id: 'skin',
    name: 'Skin & hair',
    copy: 'We’ll group the topicals into one block so they’re not competing, and keep the evidence for each one a tap away.',
    tags: ['Skin', 'Anti-Aging'],
    img: '/goals/skin.png',

  },
  {
    id: 'sleep',
    name: 'Sleep',
    copy: 'Anything that belongs in your wind-down gets scheduled there, and the app checks nothing lands too close to bed.',
    tags: ['Sleep', 'Mood'],
    img: '/goals/sleep.png',

  },
  {
    id: 'energy',
    name: 'Energy',
    copy: 'Morning items stay in the morning block, and the streak view shows whether the days you took them differ.',
    tags: ['Energy', 'Recovery'],
    img: '/goals/energy.png',

  },
  {
    id: 'focus',
    name: 'Focus',
    copy: 'The cognitive entries get their own block away from meals, with the research behind each one linked in Discover.',
    tags: ['Focus'],
    img: '/goals/focus.png',

  },
  {
    id: 'training',
    name: 'Training',
    copy: 'Recovery items are spaced around your meals, and anything that shouldn’t share a slot gets flagged when it does.',
    tags: ['Muscle', 'Recovery', 'Injury'],
    img: '/goals/training.png',

  },
  {
    id: 'immunity',
    name: 'Immunity',
    copy: 'The immune and gut entries are kept in a consistent daily slot, since these are the ones people drop first.',
    tags: ['Immune', 'Gut Health'],
    img: '/goals/immunity.png',

  },
];

export const GOAL_BY_ID = Object.fromEntries(GOALS.map((g) => [g.id, g]));

/** Used when someone reaches the results with no goals chosen. */
export const DEFAULT_GOAL_IDS = ['energy', 'immunity'];

