2	import { SCHEDULED_PRODUCT } from './support/catalogue';
3	
4	/**
5	 * The whole flow end to end, ending on Today. This is the test that fails when
6	 * a screen renders blank, a CTA stops advancing, or the flow is reordered
7	 * without the screens agreeing.
8	 */
9	test('completes onboarding and lands on the app', async ({ page, app }) => {
10	  await completeOnboarding(page);
11	
12	  // The last screen finishes itself, then hands over to the app proper.
13	  await expect(page.getByRole('heading', { name: 'Today' })).toBeVisible();
14	
15	  // What the flow collected has to have reached the tables, or the schedule it
16	  // just spent three screens building does not exist.
17	  expect(app.stub.db.schedule_items.length).toBeGreaterThan(0);
18	  const profile = app.stub.db.profiles[0];
19	  expect(profile.wake_time).toBe('07:00');
20	  expect(profile.sex).toBe('f');
21	  // The personalisation answers are written by a second update, so this also
22	  // proves that one ran rather than the first one carrying everything.
