    const ids = goalIds.length ? goalIds : DEFAULT_GOAL_IDS;
    const wanted = new Set(ids.flatMap((g) => GOAL_BY_ID[g]?.tags ?? []));
    const already = new Set(currentStack.map((s) => s.toLowerCase()));

