          rank(a.e) - rank(b.e) ||
          a.e.name.localeCompare(b.e.name),
      );

    const goalNames = ids.map((g) => GOAL_BY_ID[g]?.name ?? g);

    return {
      picks: scored.slice(0, 6).map(({ e, hits }, i) => {
