  choline: [/choline/],
  niacin: [/niacin/, /nicotinamide/, /nicotinic/],
};
const rows = [];
for (const f of ['supabase/migrations/0016_supplements_and_articles.sql','supabase/migrations/0017_library_rebuild.sql']) {
  const sql = readFileSync(f, 'utf8');
  const re = /^\s*\('([a-z0-9-]+)', '((?:[^']|'')*)', '(healing|growth|cosmetic|cognitive|other)',/gm;
  let m; while ((m = re.exec(sql))) rows.push({ slug: m[1], name: m[2].replace(/''/g, "'") });
}
console.log('rows:', rows.length);
for (const r of rows) {
  const text = `${r.name} ${r.slug}`.toLowerCase();
  const groups = Object.entries(N).filter(([, t]) => t.some((x) => x.test(text))).map(([k]) => k);
  if (groups.length) console.log(groups.join(','), '|', r.name);
}
